import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
forms={
 'pow_stretch': lambda t,p: p[0]*t**p[1]*np.exp(-p[2]*t**p[3]),
 'pow_exp_inv': lambda t,p: p[0]*t**p[1]*np.exp(-p[2]*t-p[3]/t),
 'lognorm': lambda t,p: p[0]*np.exp(-(np.log(t)-p[1])**2/p[2])*t**p[3],
 'pow_exp_sat': lambda t,p: p[0]*t**p[1]*np.exp(-p[2]*t)*(1-np.exp(-p[3]*t**p[4])),
 'hill': lambda t,p: p[0]*t**p[1]/(1+p[2]*t**p[3])*np.exp(-p[4]*t),
 'gauss_t': lambda t,p: p[0]*np.exp(-p[1]*(t-p[2])**2)*t**p[3]*np.exp(-p[4]*t),
}
for name,f in forms.items():
    best=None
    for s in range(12):
        rng=np.random.default_rng(s)
        p0=np.concatenate([rng.uniform(0.5,2,5),[1.0,1.5]])
        def res(q):
            return y-(f(t,q[:5]) if False else 0)
        def model(q):
            return f(t,q[:5])-q[5]*t**2*A**q[6]
        try:
            r=least_squares(lambda q: model(q)-y, p0, max_nfev=3000)
        except Exception as e:
            continue
        if best is None or r.cost<best.cost: best=r
    rms=np.sqrt(np.mean(best.fun**2))/np.std(y)
    print(name, 'nmse', '%.2e'%(np.mean(best.fun**2)/np.var(y)), np.round(best.x,4))
